// Package repository stores shipment positions in Postgres.
package repository

import (
	"context"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/Andas-LV/cargoflow/services/tracking/internal/repository/db"
)

// Position is one point of a shipment's route (generated by sqlc).
type Position = db.Position

type Positions struct {
	q *db.Queries
}

func NewPositions(pool *pgxpool.Pool) *Positions {
	return &Positions{q: db.New(pool)}
}

// Insert stores p. It returns false without error when a row with the same ID already
// exists, which makes event handlers that use the event ID as row ID idempotent.
func (r *Positions) Insert(ctx context.Context, p Position) (bool, error) {
	n, err := r.q.InsertPosition(ctx, db.InsertPositionParams{
		ID:         p.ID,
		ShipmentID: p.ShipmentID,
		StationID:  p.StationID,
		Station:    p.Station,
		Lat:        p.Lat,
		Lon:        p.Lon,
		Source:     p.Source,
		RecordedAt: p.RecordedAt,
	})
	if err != nil {
		return false, err
	}
	return n == 1, nil
}

// ListByShipment returns the route in chronological order.
func (r *Positions) ListByShipment(ctx context.Context, shipmentID uuid.UUID) ([]Position, error) {
	positions, err := r.q.ListPositionsByShipment(ctx, shipmentID)
	if err != nil {
		return nil, err
	}
	if positions == nil {
		positions = []Position{}
	}
	return positions, nil
}
